{"path": "expo-app/src/screens/ExportScreen.tsx", "content": "import React, { useState } from 'react';
import { View, Text, ActivityIndicator, StyleSheet, Alert, Platform } from 'react-native';
import axios from 'axios';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/PrimaryButton';

export default function ExportScreen() {
  const [loadingType, setLoadingType] = useState<null | 'csv' | 'pdf'>(null);
  const [message, setMessage] = useState('');

  const handleExport = async (type: 'csv' | 'pdf') => {
    setLoadingType(type);
    try {
      const token = await getToken();
      const response = await axios.get(`${API_URL}/export/${type}`, {
        responseType: type === 'csv' ? 'text' : 'arraybuffer',
        headers: { Authorization: `Bearer ${token}` },
      });

      // Lazy import to avoid issues on web builds
      const FileSystem = await import('expo-file-system');
      const Sharing = await import('expo-sharing');

      const cacheDir = FileSystem.cacheDirectory; // use cache directory
      const fileName = `export.${type}`;
      const uri = `${cacheDir}${fileName}`;

      if (type === 'csv') {
        // CSV is plain text; write using UTF-8
        await FileSystem.writeAsStringAsync(uri, response.data as string, {
          encoding: FileSystem.EncodingType.UTF8,
        });
      } else {
        // PDF binary; convert ArrayBuffer to base64
        const arrayBuffer = response.data as ArrayBuffer;
        const uint8 = new Uint8Array(arrayBuffer);
        let binary = '';
        for (let i = 0; i < uint8.byteLength; i++) {
          binary += String.fromCharCode(uint8[i]);
        }
        const base64 = btoa(binary);
        await FileSystem.writeAsStringAsync(uri, base64, {
          encoding: FileSystem.EncodingType.Base64,
        });
      }

      // Share the file (noop on web but safe)
      await Sharing.shareAsync(uri);
      setMessage('Report ready to share.');
    } catch (e) {
      Alert.alert('Export failed. Please try again.');
    } finally {
      setLoadingType(null);
      setTimeout(() => setMessage(''), 3000);
    }
  };

  return (
    <View style={styles.container}>
      <PrimaryButton
        title="Export CSV"
        onPress={() => handleExport('csv')}
        disabled={!!loadingType}
        accessibilityLabel="Export CSV"
      />
      <PrimaryButton
        title="Export PDF"
        onPress={() => handleExport('pdf')}
        disabled={!!loadingType}
        accessibilityLabel="Export PDF"
      />
      {loadingType && (
        <ActivityIndicator size="large" color={theme.colors.primary} style={{ marginTop: theme.spacing.md }} />
      )}
      {message ? <Text style={styles.message}>{message}</Text> : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  message: { marginTop: theme.spacing.md, color: theme.colors.success, ...theme.typography.body },
});"}

