{"path": "expo-app/src/screens/ExportScreen.tsx", "content": "import React, { useState } from 'react';
import { View, Text, ActivityIndicator, StyleSheet, Alert } from 'react-native';
import axios from 'axios';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/PrimaryButton';

export default function ExportScreen() {
  const [loadingType, setLoadingType] = useState<null | 'csv' | 'pdf'>(null);
  const [message, setMessage] = useState('');

  const handleExport = async (type: 'csv' | 'pdf') => {
    setLoadingType(type);
    try {
      const token = await getToken();
      const response = await axios.get(`${API_URL}/export/${type}`, {
        responseType: type === 'csv' ? 'text' : 'arraybuffer',
        headers: { Authorization: `Bearer ${token}` },
      });

      // Lazy import default exports to avoid web build issues
      const { default: FileSystem } = await import('expo-file-system');
      const { default: Sharing } = await import('expo-sharing');

      const cacheDir = FileSystem.cacheDirectory as string;
      const fileName = `export.${type}`;
      const uri = `${cacheDir}${fileName}`;

      if (type === 'csv') {
        // Write CSV as UTF-8 text
        await FileSystem.writeAsStringAsync(uri, response.data as string, {
          encoding: FileSystem.EncodingType.UTF8,
        });
      } else {
        // Write PDF binary as Base64 using btoa
        const arrayBuffer = response.data as ArrayBuffer;
        const uint8 = new Uint8Array(arrayBuffer);
        let binary = '';
        for (let i = 0; i < uint8.length; i++) {
          binary += String.fromCharCode(uint8[i]);
        }
        const base64 = btoa(binary);
        await FileSystem.writeAsStringAsync(uri, base64, {
          encoding: FileSystem.EncodingType.Base64,
        });
      }

      await Sharing.shareAsync(uri);
      setMessage('Report ready to share.');
    } catch (e) {
      Alert.alert('Export failed. Please try again.');
    } finally {
      setLoadingType(null);
      setTimeout(() => setMessage(''), 3000);
    }
  };

  return (
    <View style={styles.container}>
      <PrimaryButton
        title="Export CSV"
        onPress={() => handleExport('csv')}
        disabled={!!loadingType}
        accessibilityLabel="Export CSV"
      />
      <PrimaryButton
        title="Export PDF"
        onPress={() => handleExport('pdf')}
        disabled={!!loadingType}
        accessibilityLabel="Export PDF"
      />
      {loadingType && (
        <ActivityIndicator size="large" color={theme.colors.primary} style={{ marginTop: theme.spacing.md }} />
      )}
      {message ? <Text style={styles.message}>{message}</Text> : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  message: { marginTop: theme.spacing.md, color: theme.colors.success, ...theme.typography.body },
});"}

{"path": "expo-app/src/components/PrimaryButton.tsx", "content": "import React, { useState } from 'react';
import { Pressable, Text, StyleSheet, ActivityIndicator } from 'react-native';
import { theme } from '../theme';

type Props = {
  title: string;
  onPress: () => void;
  disabled?: boolean;
  loading?: boolean;
  accessibilityLabel?: string;
};

export default function PrimaryButton({ title, onPress, disabled = false, loading = false, accessibilityLabel }: Props) {
  const isDisabled = disabled || loading;

  return (
    <Pressable
      style={({ pressed }) => [
        styles.button,
        isDisabled && styles.disabled,
        pressed && !isDisabled && styles.pressed,
      ]}
      onPress={() => {
        if (!isDisabled) onPress();
      }}
      disabled={isDisabled}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel || title}
      accessibilityState={isDisabled ? { disabled: true } : undefined}
      accessible={true}
      tabIndex={0}
    >
      {loading ? (
        <ActivityIndicator size="small" color={theme.colors.onPrimary} />
      ) : (
        <Text style={[styles.text, isDisabled && styles.textDisabled]}>{title}</Text>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  button: {
    backgroundColor: theme.colors.primary,
    height: 48,
    minWidth: 120,
    borderRadius: theme.radii.md,
    justifyContent: 'center',
    alignItems: 'center',
    marginVertical: theme.spacing.md,
  },
  disabled: {
    backgroundColor: theme.colors.disabledBackground,
  },
  pressed: {
    backgroundColor: theme.colors.primaryVariant,
  },
  text: {
    color: theme.colors.onPrimary,
    ...theme.typography.button,
  },
  textDisabled: {
    color: theme.colors.disabled,
  },
});"}

