  },
  pressed: {
    backgroundColor: theme.colors.primaryVariant,
  },
  text: {
    color: theme.colors.onPrimary,
    ...theme.typography.button,
  },
  textDisabled: {
    color: theme.colors.disabled,
  },
});"}

