          title={title}
          onPress={() => handleExport(type)}
          disabled={disabled}
          color={theme.colors.primary}
          testID={`export-${type}-button`}
        />
      );
    }
    return (
      <PrimaryButton
        title={title}
        onPress={() => handleExport(type)}
        disabled={disabled}
