{"path": "expo-app/src/screens/ExportScreen.tsx", "content": "import React, { useState } from 'react';
import { View, Text, ActivityIndicator, StyleSheet, Alert, Modal, Pressable } from 'react-native';
import axios from 'axios';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/PrimaryButton';

export default function ExportScreen() {
  const [loading, setLoading] = useState(false);
  const [shareVisible, setShareVisible] = useState(false);

  const handleExport = async (type: 'csv' | 'pdf') => {
    setLoading(true);
    try {
      const token = await getToken();
      await axios.get(`${API_URL}/export/${type}`, {
        responseType: type === 'csv' ? 'text' : 'arraybuffer',
        headers: { Authorization: `Bearer ${token}` },
      });
      setShareVisible(true);
    } catch (e) {
      Alert.alert('Export failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const closeShare = () => setShareVisible(false);

  return (
    <View style={styles.container}>
      <PrimaryButton
        title="Export CSV"
        onPress={() => handleExport('csv')}
        disabled={loading}
        loading={loading}
        accessibilityLabel="Export CSV"
        testID="export-csv-button"
      />
      <PrimaryButton
        title="Export PDF"
        onPress={() => handleExport('pdf')}
        disabled={loading}
        loading={loading}
        accessibilityLabel="Export PDF"
        testID="export-pdf-button"
      />
      {loading && (
        <ActivityIndicator size="large" color={theme.colors.primary} style={{ marginTop: theme.spacing.md }} />
      )}
      <Modal
        visible={shareVisible}
        transparent={true}
        animationType="slide"
        onRequestClose={closeShare}
        accessibilityRole="dialog"
        testID="share-sheet"
      >
        <View style={styles.modalOverlay} accessible={true}>
          <View style={styles.modalContent}>
            <Text style={styles.shareMessage}>Report ready to share.</Text>
            <Pressable onPress={closeShare} style={styles.closeButton} accessibilityLabel="Close">
              <Text style={styles.closeText}>Close</Text>
            </Pressable>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  modalOverlay: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.5)',
    justifyContent: 'center',
    alignItems: 'center',
  },
  modalContent: {
    backgroundColor: theme.colors.surface,
    padding: theme.spacing.lg,
    borderRadius: theme.radii.md,
    alignItems: 'center',
  },
  shareMessage: { color: theme.colors.onSurface, ...theme.typography.body, marginBottom: theme.spacing.md },
  closeButton: {
    backgroundColor: theme.colors.primary,
    paddingHorizontal: theme.spacing.lg,
    paddingVertical: theme.spacing.sm,
    borderRadius: theme.radii.md,
  },
  closeText: { color: theme.colors.onPrimary, ...theme.typography.button },
});"}

